import {ArrowLeft,ArrowRight,BookOpen,ShieldCheck,FileText,Headphones,Users,Compass,CheckCircle2} from 'lucide-react';
import './information.css';
export const informationPages=[['about','Về Toán Ôn Thi 360'],['terms','Điều khoản sử dụng'],['privacy','Chính sách bảo mật'],['contact','Liên hệ và hỗ trợ']] as const;
const content:Record<string,{eyebrow:string;intro:string;image:string;sections:[string,string][]}>={
 about:{eyebrow:'CÙNG HIỂU TOÁN, CÙNG TIẾN BỘ',intro:'Một không gian kết nối lộ trình học, học liệu và sự đồng hành của gia đình, thầy cô. Bắt đầu từ điều học sinh cần hiểu, rồi từng bước xây dựng sự tự tin.',image:'info-about-v1.webp',sections:[['Học có lộ trình','Chọn lớp và mục tiêu để khám phá các bước học từ nền tảng đến vận dụng. Các lộ trình hiện là đề xuất minh họa, cần thẩm định trước khi dùng.'],['Hiểu cách làm','Định hướng học liệu có giải thích, ví dụ và luyện tập theo chuyên đề; ưu tiên khả năng diễn đạt cách nghĩ thay vì chỉ ghi nhớ đáp án.'],['Có người đồng hành','Thiết kế hướng tới học sinh, phụ huynh, giáo viên và đơn vị giáo dục. Kết nối tài khoản, lớp và phản hồi sẽ cần triển khai nghiệp vụ riêng.']]},
 terms:{eyebrow:'RÕ RÀNG TRƯỚC KHI BẮT ĐẦU',intro:'Dự thảo khung điều khoản để đơn vị vận hành rà soát. Đây chưa phải thỏa thuận có hiệu lực và không có thao tác chấp nhận điều khoản tại trang này.',image:'info-terms-v1.webp',sections:[['01 · Phạm vi sử dụng','Website hiện là bản xem trước giao diện. Danh mục, hồ sơ, kết quả và dịch vụ được gắn nhãn minh họa chưa phải nội dung được cung cấp chính thức.'],['02 · Tài khoản và người học nhỏ tuổi','Cần xác nhận độ tuổi sử dụng, cơ chế giám hộ, quyền từng vai trò và điều kiện tạo tài khoản trước khi vận hành. Bản hiện tại chưa có xác thực tài khoản.'],['03 · Học liệu và quyền sử dụng','Cần làm rõ chủ sở hữu, giấy phép, phạm vi tải/chia sẻ và quy trình tiếp nhận phản ánh về học liệu. Không suy từ bản minh họa rằng tài nguyên được phép tái phân phối.'],['04 · Ứng xử và nội dung','Đề xuất yêu cầu tôn trọng người học, không giả mạo và không chia sẻ thông tin riêng tư của người khác. Tiêu chí kiểm duyệt, xử lý vi phạm và khiếu nại cần được duyệt.'],['05 · Phí, hủy và hoàn tiền','Chưa có dịch vụ trả phí hoặc giao dịch tại bản xem trước. Giá, điều kiện đăng ký, hủy, hoàn tiền và trách nhiệm các bên phải được xác nhận riêng nếu triển khai.'],['06 · Hiệu lực và giải quyết tranh chấp','Đơn vị ký kết, địa chỉ pháp lý, ngày hiệu lực, luật áp dụng và đầu mối giải quyết chưa được xác nhận. Không dùng dự thảo này thay cho văn bản được rà soát pháp lý.']]},
 privacy:{eyebrow:'TÔN TRỌNG THÔNG TIN CÁ NHÂN',intro:'Khung chính sách bảo mật đang chờ xác minh hệ thống thực tế. Nội dung mô tả những vấn đề cần làm rõ, không phải chứng nhận hay cam kết bảo mật đã triển khai.',image:'info-privacy-v1.webp',sections:[['01 · Dữ liệu và mục đích','Cần lập danh mục dữ liệu tài khoản, học tập, liên hệ và nhật ký kỹ thuật; nêu mục đích và căn cứ xử lý cho từng nhóm trước khi thu thập.'],['02 · Dữ liệu học sinh','Cần xác định cơ chế giám hộ và đồng ý phù hợp, giới hạn công bố ảnh/điểm/thành tích và quyền xem theo lớp, đơn vị. Hồ sơ hiện hiển thị là dữ liệu minh họa.'],['03 · Bên nhận và lưu trữ','Nhà cung cấp dịch vụ, phạm vi chia sẻ, vị trí lưu trữ, thời hạn giữ và quy trình xóa dữ liệu chưa được xác nhận. Không đưa ra thời hạn hoặc danh sách bên nhận khi chưa kiểm kê.'],['04 · Cookie và công nghệ theo dõi','Cần kiểm kê cookie, lưu trữ trình duyệt, phân tích truy cập và công cụ bên thứ ba của bản triển khai thật. Không mặc định website không theo dõi chỉ vì chưa có form hoạt động.'],['05 · Quyền và yêu cầu của người dùng','Đề xuất quy trình yêu cầu xem, sửa hoặc xóa dữ liệu, xác minh người yêu cầu và xử lý theo quy định áp dụng. Kênh tiếp nhận và thời hạn xử lý đang chờ xác nhận.'],['06 · An toàn và thay đổi chính sách','Cần thẩm định kiểm soát truy cập, lưu trữ, sao lưu, xử lý sự cố và cơ chế thông báo thay đổi. Không có bảo đảm an toàn tuyệt đối hoặc chứng nhận tuân thủ từ bản thiết kế.']]},
 contact:{eyebrow:'BẮT ĐẦU TỪ MỘT CÂU HỎI',intro:'Tìm đúng nhóm vấn đề để chuẩn bị yêu cầu rõ ràng. Các kênh hỗ trợ chính thức chưa được cấu hình; trang này chưa nhận hay gửi thông tin liên hệ.',image:'info-contact-v1.webp',sections:[['Tư vấn học tập','Chuẩn bị lớp đang học, mục tiêu và nội dung còn vướng. Chưa cần cung cấp họ tên, số điện thoại hoặc kết quả học tập cá nhân trong bản xem trước.'],['Hỗ trợ sử dụng','Ghi lại tên trang, thao tác và thông báo lỗi. Nếu chụp màn hình, hãy che thông tin riêng tư; không gửi mật khẩu hoặc mã xác thực.'],['Hợp tác giáo dục','Chuẩn bị nội dung đề xuất, phạm vi chuyên môn và khu vực hoạt động. Chưa có biểu mẫu tiếp nhận hoặc thỏa thuận hợp tác tại đây.']]}
};
export default function InformationPage({tab,onNavigate,onHome}:{tab:string;onNavigate:(tab:string)=>void;onHome:()=>void}){
 const data=content[tab]||content.about;const title=informationPages.find(p=>p[0]===tab)?.[1];const legal=tab==='terms'||tab==='privacy';
 return <article className={`info-page info-${tab}`}><nav className="info-breadcrumb" aria-label="Đường dẫn"><button onClick={onHome}><ArrowLeft size={15}/> Trang chủ</button><span>/</span><span>{title}</span></nav>
 <section className="info-hero"><div><span className="eyebrow">{data.eyebrow}</span><h1>{title}</h1><p>{data.intro}</p><span className="info-status">{legal?'Dự thảo · Chưa có hiệu lực':'Bản giới thiệu minh họa'}</span></div><img src={`/assets/toan/${data.image}`} alt={tab==='about'?'Minh họa cô giáo đồng hành cùng học sinh':tab==='contact'?'Minh họa tư vấn học tập':tab==='privacy'?'Minh họa học sinh và bảo vệ thông tin':'Minh họa trao đổi các nguyên tắc học tập'}/></section>
 <nav className="info-tabs" aria-label="Các trang thông tin">{informationPages.map(([key,label])=><button key={key} aria-current={key===tab?'page':undefined} onClick={()=>onNavigate(key)}>{label}</button>)}</nav>
 {legal&&<aside className="info-draft"><ShieldCheck size={23}/><div><strong>Cần đơn vị vận hành và người phụ trách pháp lý xác nhận</strong><p>Chưa xác nhận chủ thể pháp lý, thông tin liên hệ và ngày hiệu lực. Các mục dưới đây là nội dung soạn thảo để hoàn thiện, không phải chính sách đã được thông qua.</p></div></aside>}
 <div className={legal?'info-document-layout':'info-content-layout'}>{legal&&<aside className="info-toc"><h2>Nội dung trang</h2>{data.sections.map(([heading],i)=><a key={heading} href={`#${tab}-${i}`}>{heading}</a>)}<small>Bản dự thảo 09/11/2026<br/>Chưa có ngày hiệu lực</small></aside>}
 <div className={legal?'info-sections':'info-cards'}>{data.sections.map(([heading,body],i)=><section id={`${tab}-${i}`} key={heading} className="info-card"><span className="info-card-icon">{legal?<FileText size={22}/>:i===0?<Compass size={23}/>:i===1?<BookOpen size={23}/>:<Users size={23}/>}</span><h2>{heading}</h2><p>{body}</p></section>)}</div></div>
 {tab==='about'&&<section className="info-feature"><div className="info-journey-art" aria-label="Ba bước học tập gợi ý">{[[Compass,"Chọn mục tiêu"],[BookOpen,"Học và luyện tập"],[Users,"Cùng nhìn lại"]].map(([Icon,label],i)=>{const Symbol=Icon as typeof Compass;return <div key={String(label)}><span>0{i+1}</span><Symbol size={35}/><strong>{String(label)}</strong></div>})}</div><div><span className="eyebrow">MỖI NGƯỜI MỘT VAI TRÒ</span><h2>Học sinh chủ động. Gia đình thấu hiểu. Thầy cô dẫn dắt.</h2><p>Giao diện kết nối lớp học, tài liệu, luyện đề và giáo viên đồng hành trong cùng một hành trình. Thông tin hồ sơ và kết quả cần được xác minh trước khi công bố.</p><button className="button primary" onClick={()=>onNavigate('roadmaps')}>Khám phá lộ trình <ArrowRight size={16}/></button></div></section>}
 {tab==='contact'&&<section className="info-contact-panel"><div><Headphones size={30}/><h2>Kênh liên hệ chính thức</h2><p>Đang chờ đơn vị quản lý cung cấp và xác minh.</p><dl>{['Email hỗ trợ','Số điện thoại','Địa chỉ tiếp nhận','Thời gian hỗ trợ'].map(x=><div key={x}><dt>{x}</dt><dd>Chưa công bố</dd></div>)}</dl></div><div className="info-help"><h2>Trước khi liên hệ</h2>{[['Có thể đăng ký học ngay không?','Chưa. Đây là giao diện thử nghiệm, chưa có dịch vụ đăng ký học hoạt động.'],['Trang này có nhận yêu cầu không?','Không có biểu mẫu gửi và không có yêu cầu nào được tạo từ trang này.'],['Làm sao tìm đúng lộ trình?','Chọn lớp ở trang lộ trình, xem mục tiêu và nội dung minh họa trước khi trao đổi với giáo viên.']].map(([q,a])=><details key={q}><summary>{q}</summary><p>{a}</p></details>)}</div></section>}
 <section className="info-next"><CheckCircle2 size={24}/><div><h2>{legal?'Minh bạch từ bản thiết kế':'Cùng khám phá bước học tiếp theo'}</h2><p>{legal?'Thông tin chính thức sẽ được cập nhật sau khi xác minh và phê duyệt.':'Tìm hiểu lộ trình và học liệu mẫu, không cần nhập thông tin cá nhân.'}</p></div><button className="button soft" onClick={legal?()=>onNavigate('contact'):onHome}>{legal?'Liên hệ và hỗ trợ':'Về trang chủ'}<ArrowRight size={16}/></button></section>
 </article>
}
